'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const presets={original:'none',film:'sepia(.3) saturate(.85) contrast(1.08) brightness(1.03)',warm:'sepia(.45) saturate(1.15) brightness(1.04)',mono:'grayscale(1) contrast(1.1)'};
let info,file,preset='film',previewURL,xhr,items=[],next=0,loading=false;
function notice(text,error=false){$('#status').textContent=text;$('#status').classList.toggle('error',error);}
async function api(path,body){const r=await fetch('/api/album/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Temu-Album':'1'},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Album belum dapat diakses.');return data;}
function choosePreset(value){preset=Object.hasOwn(presets,value)?value:'original';for(const button of document.querySelectorAll('[data-filter]'))button.setAttribute('aria-pressed',String(button.dataset.filter===preset));for(const el of [$('#photo-preview'),$('#video-preview'),$('#camera-live')])el.style.filter=presets[preset];}
function prettyDate(value){return new Date(value).toLocaleString('id-ID',{dateStyle:'long',timeStyle:'short',timeZone:'Asia/Jakarta'})+' WIB';}
function applyInfo(data){info=data;$('#count').textContent=data.count;$('#upload').disabled=!file||!info.uploadsOpen;$('#take-photo').disabled=$('#take-video').disabled=!info.uploadsOpen;$('#locked').hidden=data.revealed;$('#release-copy').textContent=data.releaseAt?'Galeri dibuka pada '+prettyDate(data.releaseAt)+'.':'';notice(data.uploadsOpen?'Album '+data.title+' · Bagikan momen favoritmu.':'Unggahan sudah ditutup. Kenangan tetap dapat dilihat saat galeri dibuka.');}
async function init(){try{const key=new URLSearchParams(location.hash.slice(1)).get('k');const data=key?await api('join',{key}):await api('info');if(key)history.replaceState(null,'',location.pathname);applyInfo(data);choosePreset(data.filter);$('#gate').hidden=true;$('#content').hidden=false;}catch(e){$('#gate').hidden=false;$('#content').hidden=true;notice(e.message,true);}}
function selectFile(f){if(!f)return;if(f.size>100*1024*1024){notice('File terlalu besar. Pilih file maksimal 100 MB.',true);return;}if(!['image/jpeg','image/png','image/webp','video/mp4','video/quicktime','video/webm'].includes(f.type)){notice('Gunakan JPG, PNG, WebP atau video MP4, MOV, WebM. Untuk HEIC, ubah ke JPG dahulu.',true);return;}if(previewURL)URL.revokeObjectURL(previewURL);file=f;previewURL=URL.createObjectURL(f);const isPhoto=f.type.startsWith('image/');$('#photo-preview').hidden=!isPhoto;$('#video-preview').hidden=isPhoto;$('#video-preview').pause();$('#video-preview').removeAttribute('src');(isPhoto?$('#photo-preview'):$('#video-preview')).src=previewURL;$('#placeholder').hidden=true;$('#file-info').textContent=f.name+' · '+(f.size/1024/1024).toFixed(1)+' MB';$('#upload').disabled=!info?.uploadsOpen;choosePreset(preset);notice('Momen siap dibagikan. Pilih nuansa, lalu simpan ke album.');}
$('#take-photo').onclick=()=>TemuAlbumCamera.open('photo',selectFile);
$('#take-video').onclick=()=>TemuAlbumCamera.open('video',selectFile);
$('#filters').onclick=e=>{const button=e.target.closest('[data-filter]');if(button)choosePreset(button.dataset.filter);};
$('#retry').onclick=init;
function tab(gallery){$('#capture').hidden=gallery;$('#gallery').hidden=!gallery;for(const [id,active] of [['tab-capture',!gallery],['tab-gallery',gallery]]){$('#'+id).classList.toggle('selected',active);$('#'+id).setAttribute('aria-pressed',String(active));}if(gallery)loadGallery(true);}
$('#tab-capture').onclick=()=>tab(false);$('#tab-gallery').onclick=()=>tab(true);
$('#upload-form').onsubmit=async e=>{e.preventDefault();if(!file||xhr||!info?.uploadsOpen)return;const name=$('#guest-name').value.trim();if(!name)return;const currentFile=file,currentPreset=preset;$('#upload').disabled=true;$('#progress').hidden=false;$('#progress').value=0;$('#cancel-upload').hidden=false;notice('Mengunggah momenmu… Jangan tutup halaman ini.');xhr=new XMLHttpRequest();xhr.open('PUT','/api/album/upload');xhr.timeout=180000;for(const [k,v] of Object.entries({'Content-Type':currentFile.type,'X-Temu-Album':'1','X-Album-Name':encodeURIComponent(name),'X-Album-Caption':encodeURIComponent($('#caption').value.trim()),'X-Album-Filter':currentPreset}))xhr.setRequestHeader(k,v);xhr.upload.onprogress=e=>{if(e.lengthComputable)$('#progress').value=e.loaded/e.total*100;};xhr.onload=async()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status!==201)throw Error(data.error);notice('Momen tersimpan. Terima kasih sudah berbagi!');$('#cancel-upload').hidden=true;if(currentFile.type.startsWith('image/'))await uploadThumbnail(currentFile,data.id,data.thumbnailKey);if(file===currentFile){file=null;$('#photo-preview').hidden=$('#video-preview').hidden=true;$('#video-preview').pause();$('#placeholder').hidden=false;$('#file-info').textContent='Momen tersimpan. Ambil foto berikutnya?';$('#caption').value='';for(const el of document.querySelectorAll('input[type=file]'))el.value='';if(previewURL)URL.revokeObjectURL(previewURL);}info.count++;$('#count').textContent=info.count;}catch(e){notice(e.message||'Unggahan gagal. Silakan ulangi.',true);}finish();};xhr.onerror=xhr.ontimeout=()=>{notice('Koneksi terputus. File belum terkonfirmasi tersimpan; silakan ulangi.',true);finish();};xhr.onabort=()=>{notice('Unggahan dibatalkan. Pilihan file tetap tersedia.');finish();};xhr.send(currentFile);};
async function uploadThumbnail(source,id,key){try{const image=await createImageBitmap(source,{resizeWidth:720});const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0);image.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.72));if(!blob||blob.size>512*1024)return;await fetch('/api/album/thumbnail/'+id,{method:'PUT',headers:{'Content-Type':'image/jpeg','X-Temu-Album':'1','X-Album-Thumbnail-Key':key},body:blob,signal:AbortSignal.timeout(15000)});}catch{/* Original stays saved even if a lightweight preview cannot be generated. */}}
function finish(){xhr=null;$('#upload').disabled=!file||!info.uploadsOpen;$('#progress').hidden=$('#cancel-upload').hidden=true;}
$('#cancel-upload').onclick=()=>xhr?.abort();
function renderGallery(){const type=$('#media-type').value;$('#grid').innerHTML=items.filter(item=>type==='all'||(type==='photo')===item.mime.startsWith('image/')).map(item=>`<button class="moment-card" data-id="${item.id}" aria-label="Buka momen dari ${esc(item.name)}">${item.mime.startsWith('image/')?`<img class="moment-photo filter-${item.filter}" src="/api/album/file/${item.id}${item.thumbnail?'?thumb=1':''}" loading="lazy" decoding="async" alt="Momen dari ${esc(item.name)}">`:'<div class="moment-video"><span>▷</span><small>VIDEO · KENANGAN BERGERAK</small></div>'}<h3>${esc(item.name)}</h3>${item.caption?`<p class="caption">${esc(item.caption)}</p>`:''}<p><time>${esc(prettyDate(item.created))}</time></p></button>`).join('');$('#gallery-empty').hidden=!info.revealed||!!$('#grid').childElementCount;$('#more').hidden=next===null||!info.revealed;}
async function loadGallery(reset=false){if(loading)return;loading=true;$('#refresh').disabled=true;try{applyInfo(await api('info'));if(!info.revealed){items=[];next=null;renderGallery();return;}if(reset){items=[];next=0;}const data=await api('items?offset='+(next||0));items.push(...data.items);next=data.next;renderGallery();}catch(e){notice(e.message,true);}finally{loading=false;$('#refresh').disabled=false;}}
$('#refresh').onclick=()=>loadGallery(true);$('#more').onclick=()=>loadGallery();$('#media-type').onchange=renderGallery;
$('#grid').onclick=e=>{const card=e.target.closest('[data-id]');if(!card)return;const item=items.find(x=>x.id===card.dataset.id);const photo=item.mime.startsWith('image/');$('#moment-detail').innerHTML=`<h2>${esc(item.name)}</h2><p>${esc(item.caption)}</p>${photo?`<img class="detail-media filter-${item.filter}" src="/api/album/file/${item.id}" alt="Momen dari ${esc(item.name)}">`:`<video class="detail-media filter-${item.filter}" src="/api/album/file/${item.id}" controls playsinline preload="metadata"></video>`}<div class="detail-actions"><a class="solid" href="/api/album/file/${item.id}?download=1" download>Unduh file asli ↗</a>${photo&&item.filter!=='original'?'<button class="outline" id="save-filtered">Siapkan foto dengan filter</button>':''}</div><p class="small">File asli diunduh tanpa kompresi. Nuansa video berlaku pada tampilan pemutar.</p>`;$('#moment-dialog').showModal();if(photo&&item.filter!=='original')$('#save-filtered').onclick=async()=>{const button=$('#save-filtered');button.disabled=true;try{const r=await fetch('/api/album/file/'+item.id);if(!r.ok)throw Error('File belum tersedia.');const image=await createImageBitmap(await r.blob());const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');if(!('filter' in ctx))throw Error('Browser ini belum mendukung simpan filter. Gunakan unduh file asli.');ctx.filter=presets[item.filter];ctx.drawImage(image,0,0);image.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.98));if(!blob)throw Error('Foto terlalu besar untuk diproses pada perangkat ini. Unduh file asli.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='momen-'+item.id.slice(0,8)+'-'+item.filter+'.jpg';a.className='outline';a.textContent='Unduh foto dengan filter ↗';button.replaceWith(a);$('#moment-dialog').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}catch(e){const error=document.createElement('p');error.className='small';error.setAttribute('role','alert');error.textContent=e.message;button.after(error);}finally{button.disabled=false;}};};
$('#close-dialog').onclick=()=>$('#moment-dialog').close();$('#moment-dialog').addEventListener('close',()=>{$('#moment-dialog video')?.pause();});
window.addEventListener('beforeunload',e=>{if(xhr){e.preventDefault();e.returnValue='';}});
// Refresh reveal time without forcing a guest to reload the page.
setInterval(()=>{if(info&&!document.hidden&&!$('#gallery').hidden&&!loading&&!info.revealed)loadGallery(true);},30000);
init();

window.addEventListener('hashchange',()=>{if(new URLSearchParams(location.hash.slice(1)).has('k'))init();});
